before.lib/counter.ex:
defmodule Counter do
  @moduledoc "Application counter; public operations are start_link, add and value, not its storage."
  def start_link, do: Agent.start_link(fn -> %{value: 0} end)
  def add(pid, n), do: Agent.update(pid, &%{value: &1.value + n})
  def value(pid), do: Agent.get(pid, & &1.value)
end

after.lib/counter.ex:
defmodule Counter do
  @moduledoc "Application counter; public operations are start_link, add and value, not its storage."
  def start_link, do: Agent.start_link(fn -> 0 end)
  def add(pid, n), do: Agent.update(pid, &(&1 + n))
  def value(pid), do: Agent.get(pid, & &1)
end
